using Microsoft.AspNetCore.SignalR;using RoomReservation.Domain.Entities;namespace RoomReservation.Api.Hubs;public sealed class ReservationEvents(IHubContext<ScheduleHub> schedule,IHubContext<QrHub> qr){public Task Created(Booking b)=>schedule.Clients.All.SendAsync("BookingCreated",b);public Task Updated(Booking b)=>schedule.Clients.All.SendAsync("BookingUpdated",b);public Task Cancelled(Booking b)=>schedule.Clients.All.SendAsync("BookingCancelled",b);public Task CheckedIn(Booking b)=>schedule.Clients.All.SendAsync("RoomCheckedIn",new{room_id=b.RoomId,booking_id=b.Id});public Task CheckedOut(Booking b)=>schedule.Clients.All.SendAsync("RoomCheckedOut",new{room_id=b.RoomId,booking_id=b.Id});public Task Rotated(Guid room,string token,DateTime expires)=>qr.Clients.All.SendAsync("TokenRotated",new{room_id=room,token,expires_at=expires});}
